// Parse Evolution webhook payload and extract message details.
// Evolution sends different event types; we only care about messages.upsert
// with fromMe=false (inbound messages from others).

const body = $input.first().json.body || $input.first().json;

// Check event type
const event = body.event;
if (event !== 'messages.upsert') {
  return [{ json: { _action: 'ignore', reason: `event_type: ${event}` } }];
}

const data = body.data || body;
const key = data.key || {};

// Ignore messages sent by us
if (key.fromMe === true) {
  return [{ json: { _action: 'ignore', reason: 'from_me' } }];
}

// Ignore group messages (only handle 1:1 chats)
const remoteJid = key.remoteJid || '';
if (remoteJid.includes('@g.us')) {
  return [{ json: { _action: 'ignore', reason: 'group_message' } }];
}

// Extract phone number (strip @s.whatsapp.net)
const phone = remoteJid.replace('@s.whatsapp.net', '');

// Extract message text from various message types
let text = '';
const msg = data.message || {};
if (msg.conversation) {
  text = msg.conversation;
} else if (msg.extendedTextMessage && msg.extendedTextMessage.text) {
  text = msg.extendedTextMessage.text;
} else if (msg.buttonsResponseMessage) {
  text = msg.buttonsResponseMessage.selectedDisplayText || '';
} else if (msg.listResponseMessage) {
  text = msg.listResponseMessage.title || '';
} else if (msg.templateButtonReplyMessage) {
  text = msg.templateButtonReplyMessage.selectedDisplayText || '';
} else {
  // Image, audio, video, document, etc. - not handled yet
  return [{ json: { _action: 'ignore', reason: 'unsupported_message_type' } }];
}

// Extract metadata
const pushName = data.pushName || '';
const messageId = key.id || '';
const timestamp = data.messageTimestamp || Math.floor(Date.now() / 1000);
const instanceName = body.instance || '';

return [{
  json: {
    _action: 'process',
    phone,
    text: text.trim(),
    pushName,
    messageId,
    timestamp,
    instanceName,
    remoteJid
  }
}];

// Determine routing based on dedup + classification results.
// Input: the parsed message from 'Parse Evolution Payload' + DB classification.

const parsed = $('Parse Evolution Payload').first().json;
const db = $input.first().json;

// If message was already processed (dedup), ignore
if (!db.new_message_id && db.new_message_id !== 0) {
  return [{ json: { route: 'ignore', reason: 'duplicate_message' } }];
}

const phone = parsed.phone;
const text = parsed.text;
const pushName = parsed.pushName;
const messageId = parsed.messageId;

// Check if sender is an agent
if (db.is_agent) {
  // Check if message is a TOMO claim
  const tomoMatch = text.match(/^TOMO-([A-Z0-9]{4})$/i);
  if (tomoMatch) {
    return [{
      json: {
        route: 'agent_claim',
        agent_id: db.agent_id,
        agent_name: db.agent_name,
        agent_phone: phone,
        short_code: tomoMatch[1].toUpperCase(),
        raw_message: text,
        messageId
      }
    }];
  }
  // Agent sent a non-TOMO message -> follow-up reply (WF15 decides relevance)
  return [{ json: { route: 'agent_followup_reply', agent_id: db.agent_id, agent_name: db.agent_name, agent_phone: phone, text, messageId } }];
}

// Not an agent - check conversation status
if (!db.conversation_id) {
  // New lead - no conversation exists
  return [{
    json: {
      route: 'new_lead',
      phone,
      pushName,
      text,
      messageId
    }
  }];
}

// Existing conversation - route by mode
const mode = db.conv_mode;
if (mode === 'ai') {
  return [{
    json: {
      route: 'ai_conversation',
      conversation_id: db.conversation_id,
      phone,
      pushName,
      text,
      messageId,
      current_property: db.current_property,
      assigned_agent_id: db.assigned_agent_id
    }
  }];
}

if (mode === 'human') {
  return [{
    json: {
      route: 'human_forward',
      conversation_id: db.conversation_id,
      phone,
      pushName,
      text,
      messageId,
      assigned_agent_id: db.assigned_agent_id,
      assigned_agent_phone: db.assigned_agent_phone
    }
  }];
}

if (mode === 'pending_assignment') {
  return [{
    json: {
      route: 'pending',
      conversation_id: db.conversation_id,
      phone,
      pushName,
      text,
      messageId
    }
  }];
}

// Fallback
return [{ json: { route: 'ignore', reason: 'unknown_mode' } }];

// Forward lead message to assigned agent via Evolution.
// In human mode, the bot acts as a relay.
const data = $input.first().json;

const forwardBody = [
  `Mensaje de ${data.pushName || 'Lead'} (${data.phone}):`,
  ``,
  data.text
].join('\n');

return [{
  json: {
    number: data.assigned_agent_phone,
    text: forwardBody,
    conversation_id: data.conversation_id,
    phone: data.phone
  }
}];

